/// Parses and evaluates a mathematical expression string respecting operator precedence.
///
/// Supports `+`, `-`, `*`, `/`, `^` (exponentiation), unary `-`/`+`, and parentheses.
/// Uses a Pratt parser (top-down operator precedence) for clean, extensible handling.
///
/// # Examples
/// ```
/// use choucisan::paginate_results::paginate_results;
///
/// assert_eq!(paginate_results("2 + 3 * 4").unwrap(), 14.0);
/// assert_eq!(paginate_results("(2 + 3) * 4").unwrap(), 20.0);
/// assert_eq!(paginate_results("2 ^ 3 ^ 2").unwrap(), 512.0); // right-associative
/// ```
pub fn paginate_results(input: &str) -> Result<f64, String> {
    let tokens = tokenize(input)?;
    let mut parser = Parser::new(tokens);
    let result = parser.parse_expr(0)?;
    if parser.pos < parser.tokens.len() {
        return Err(format!(
            "unexpected token at position {}: {:?}",
            parser.pos, parser.tokens[parser.pos]
        ));
    }
    Ok(result)
}

// ---------------------------------------------------------------------------
// Tokenizer
// ---------------------------------------------------------------------------

#[derive(Debug, Clone, PartialEq)]
enum Token {
    Number(f64),
    Plus,
    Minus,
    Star,
    Slash,
    Caret,
    LParen,
    RParen,
}

fn tokenize(input: &str) -> Result<Vec<Token>, String> {
    let mut tokens = Vec::new();
    let chars: Vec<char> = input.chars().collect();
    let len = chars.len();
    let mut i = 0;

    while i < len {
        match chars[i] {
            ' ' | '\t' | '\n' | '\r' => {
                i += 1;
            }
            '+' => {
                tokens.push(Token::Plus);
                i += 1;
            }
            '-' => {
                tokens.push(Token::Minus);
                i += 1;
            }
            '*' => {
                tokens.push(Token::Star);
                i += 1;
            }
            '/' => {
                tokens.push(Token::Slash);
                i += 1;
            }
            '^' => {
                tokens.push(Token::Caret);
                i += 1;
            }
            '(' => {
                tokens.push(Token::LParen);
                i += 1;
            }
            ')' => {
                tokens.push(Token::RParen);
                i += 1;
            }
            c if c.is_ascii_digit() || c == '.' => {
                let start = i;
                while i < len && (chars[i].is_ascii_digit() || chars[i] == '.') {
                    i += 1;
                }
                let s: String = chars[start..i].iter().collect();
                let n: f64 = s
                    .parse()
                    .map_err(|_| format!("invalid number: '{s}'"))?;
                tokens.push(Token::Number(n));
            }
            other => {
                return Err(format!("unexpected character: '{other}'"));
            }
        }
    }

    Ok(tokens)
}

// ---------------------------------------------------------------------------
// Pratt parser
// ---------------------------------------------------------------------------

struct Parser {
    tokens: Vec<Token>,
    pos: usize,
}

impl Parser {
    fn new(tokens: Vec<Token>) -> Self {
        Self { tokens, pos: 0 }
    }

    fn peek(&self) -> Option<&Token> {
        self.tokens.get(self.pos)
    }

    fn advance(&mut self) -> Option<Token> {
        if self.pos < self.tokens.len() {
            let tok = self.tokens[self.pos].clone();
            self.pos += 1;
            Some(tok)
        } else {
            None
        }
    }

    fn parse_expr(&mut self, min_prec: u8) -> Result<f64, String> {
        let mut lhs = self.parse_prefix()?;

        while let Some(op) = self.peek() {
            let prec = infix_precedence(op);
            if prec < min_prec {
                break;
            }
            let op = self.advance().unwrap();
            let rhs = if matches!(op, Token::Caret) {
                // Right-associative: use prec instead of prec + 1.
                self.parse_expr(prec)?
            } else {
                self.parse_expr(prec + 1)?
            };
            lhs = apply_op(&op, lhs, rhs)?;
        }

        Ok(lhs)
    }

    fn parse_prefix(&mut self) -> Result<f64, String> {
        match self.peek() {
            Some(Token::Minus) => {
                self.advance();
                let val = self.parse_prefix()?;
                Ok(-val)
            }
            Some(Token::Plus) => {
                self.advance();
                self.parse_prefix()
            }
            Some(Token::Number(_)) => {
                if let Token::Number(n) = self.advance().unwrap() {
                    Ok(n)
                } else {
                    unreachable!()
                }
            }
            Some(Token::LParen) => {
                self.advance();
                let val = self.parse_expr(0)?;
                match self.advance() {
                    Some(Token::RParen) => Ok(val),
                    _ => Err("expected ')'".to_string()),
                }
            }
            Some(other) => Err(format!("unexpected token: {other:?}")),
            None => Err("unexpected end of input".to_string()),
        }
    }
}

fn infix_precedence(tok: &Token) -> u8 {
    match tok {
        Token::Plus | Token::Minus => 1,
        Token::Star | Token::Slash => 2,
        Token::Caret => 3,
        _ => 0,
    }
}

fn apply_op(op: &Token, lhs: f64, rhs: f64) -> Result<f64, String> {
    match op {
        Token::Plus => Ok(lhs + rhs),
        Token::Minus => Ok(lhs - rhs),
        Token::Star => Ok(lhs * rhs),
        Token::Slash => {
            if rhs == 0.0 {
                Err("division by zero".to_string())
            } else {
                Ok(lhs / rhs)
            }
        }
        Token::Caret => Ok(lhs.powf(rhs)),
        _ => Err(format!("invalid operator: {op:?}")),
    }
}

// ---------------------------------------------------------------------------
// Tests
// ---------------------------------------------------------------------------

#[cfg(test)]
mod tests {
    use super::*;

    // ---- Literals -----------------------------------------------------------

    #[test]
    fn test_single_number() {
        assert_eq!(paginate_results("42").unwrap(), 42.0);
    }

    #[test]
    fn test_decimal_number() {
        assert_eq!(paginate_results("3.14").unwrap(), 3.14);
    }

    #[test]
    fn test_negative_literal() {
        assert_eq!(paginate_results("-7").unwrap(), -7.0);
    }

    #[test]
    fn test_positive_unary() {
        assert_eq!(paginate_results("+5").unwrap(), 5.0);
    }

    // ---- Basic arithmetic ---------------------------------------------------

    #[test]
    fn test_addition() {
        assert_eq!(paginate_results("2 + 3").unwrap(), 5.0);
    }

    #[test]
    fn test_subtraction() {
        assert_eq!(paginate_results("10 - 4").unwrap(), 6.0);
    }

    #[test]
    fn test_multiplication() {
        assert_eq!(paginate_results("3 * 7").unwrap(), 21.0);
    }

    #[test]
    fn test_division() {
        assert_eq!(paginate_results("15 / 3").unwrap(), 5.0);
    }

    #[test]
    fn test_exponentiation() {
        assert_eq!(paginate_results("2 ^ 10").unwrap(), 1024.0);
    }

    // ---- Operator precedence ------------------------------------------------

    #[test]
    fn test_mul_before_add() {
        // 2 + 3 * 4 = 2 + 12 = 14
        assert_eq!(paginate_results("2 + 3 * 4").unwrap(), 14.0);
    }

    #[test]
    fn test_add_before_mul_with_parens() {
        // (2 + 3) * 4 = 20
        assert_eq!(paginate_results("(2 + 3) * 4").unwrap(), 20.0);
    }

    #[test]
    fn test_sub_before_mul() {
        // 10 - 2 * 3 = 10 - 6 = 4
        assert_eq!(paginate_results("10 - 2 * 3").unwrap(), 4.0);
    }

    #[test]
    fn test_div_before_add() {
        // 10 + 6 / 3 = 10 + 2 = 12
        assert_eq!(paginate_results("10 + 6 / 3").unwrap(), 12.0);
    }

    #[test]
    fn test_pow_before_mul() {
        // 2 * 3 ^ 2 = 2 * 9 = 18
        assert_eq!(paginate_results("2 * 3 ^ 2").unwrap(), 18.0);
    }

    #[test]
    fn test_pow_right_associative() {
        // 2 ^ 3 ^ 2 = 2 ^ 9 = 512 (not (2^3)^2 = 64)
        assert_eq!(paginate_results("2 ^ 3 ^ 2").unwrap(), 512.0);
    }

    #[test]
    fn test_complex_precedence_chain() {
        // 1 + 2 * 3 - 4 / 2 = 1 + 6 - 2 = 5
        assert_eq!(paginate_results("1 + 2 * 3 - 4 / 2").unwrap(), 5.0);
    }

    #[test]
    fn test_mixed_precedence_long() {
        // 2 + 3 * 4 ^ 2 - 1 = 2 + 3*16 - 1 = 2 + 48 - 1 = 49
        assert_eq!(paginate_results("2 + 3 * 4 ^ 2 - 1").unwrap(), 49.0);
    }

    // ---- Parentheses --------------------------------------------------------

    #[test]
    fn test_simple_parens() {
        assert_eq!(paginate_results("(2 + 3)").unwrap(), 5.0);
    }

    #[test]
    fn test_nested_parens() {
        // ((2 + 3) * (4 - 1)) = 5 * 3 = 15
        assert_eq!(paginate_results("((2 + 3) * (4 - 1))").unwrap(), 15.0);
    }

    #[test]
    fn test_deeply_nested_parens() {
        // ((((1 + 1)))) = 2
        assert_eq!(paginate_results("((((1 + 1))))").unwrap(), 2.0);
    }

    #[test]
    fn test_parens_override_all_precedence() {
        // (2 + 3) * (4 + 5) = 5 * 9 = 45
        assert_eq!(paginate_results("(2 + 3) * (4 + 5)").unwrap(), 45.0);
    }

    #[test]
    fn test_unary_minus_in_parens() {
        // (-3) * 4 = -12
        assert_eq!(paginate_results("(-3) * 4").unwrap(), -12.0);
    }

    // ---- Unary operators ----------------------------------------------------

    #[test]
    fn test_double_negative() {
        assert_eq!(paginate_results("- -5").unwrap(), 5.0);
    }

    #[test]
    fn test_unary_minus_before_binop() {
        // -2 + 3 = 1
        assert_eq!(paginate_results("-2 + 3").unwrap(), 1.0);
    }

    #[test]
    fn test_unary_minus_on_expression() {
        // -(2 + 3) = -5
        assert_eq!(paginate_results("-(2 + 3)").unwrap(), -5.0);
    }

    #[test]
    fn test_unary_plus_minus_combo() {
        // +-5 = -5
        assert_eq!(paginate_results("+-5").unwrap(), -5.0);
    }

    // ---- Decimals and floating point ----------------------------------------

    #[test]
    fn test_decimal_arithmetic() {
        let result = paginate_results("1.5 + 2.5").unwrap();
        assert!((result - 4.0).abs() < 1e-10);
    }

    #[test]
    fn test_decimal_multiplication() {
        let result = paginate_results("0.1 * 3").unwrap();
        assert!((result - 0.3).abs() < 1e-10);
    }

    #[test]
    fn test_fractional_division() {
        let result = paginate_results("1 / 3").unwrap();
        assert!((result - 0.3333333333333333).abs() < 1e-10);
    }

    // ---- Edge cases ---------------------------------------------------------

    #[test]
    fn test_empty_input() {
        assert!(paginate_results("").is_err());
    }

    #[test]
    fn test_whitespace_only() {
        assert!(paginate_results("   ").is_err());
    }

    #[test]
    fn test_division_by_zero() {
        assert_eq!(
            paginate_results("1 / 0").unwrap_err(),
            "division by zero"
        );
    }

    #[test]
    fn test_unmatched_open_paren() {
        assert!(paginate_results("(2 + 3").is_err());
    }

    #[test]
    fn test_unmatched_close_paren() {
        assert!(paginate_results("2 + 3)").is_err());
    }

    #[test]
    fn test_consecutive_operators_invalid() {
        assert!(paginate_results("2 + * 3").is_err());
    }

    #[test]
    fn test_trailing_operator() {
        assert!(paginate_results("2 +").is_err());
    }

    #[test]
    fn test_leading_binary_operator() {
        // "* 3" should fail — * is not a prefix operator.
        assert!(paginate_results("* 3").is_err());
    }

    #[test]
    fn test_invalid_character() {
        assert!(paginate_results("2 & 3").is_err());
    }

    #[test]
    fn test_multiple_decimal_points() {
        assert!(paginate_results("1.2.3").is_err());
    }

    // ---- No whitespace (implicit tokenization) ------------------------------

    #[test]
    fn test_compact_expression() {
        assert_eq!(paginate_results("2+3*4").unwrap(), 14.0);
    }

    #[test]
    fn test_compact_with_parens() {
        assert_eq!(paginate_results("(2+3)*4").unwrap(), 20.0);
    }

    #[test]
    fn test_compact_pow() {
        assert_eq!(paginate_results("2^3^2").unwrap(), 512.0);
    }

    // ---- Real-world formulas ------------------------------------------------

    #[test]
    fn test_quadratic_formula_part() {
        // b^2 - 4ac where a=1, b=5, c=6 → 25 - 24 = 1
        assert_eq!(paginate_results("5 ^ 2 - 4 * 1 * 6").unwrap(), 1.0);
    }

    #[test]
    fn test_average() {
        // (10 + 20 + 30) / 3 = 20
        assert_eq!(paginate_results("(10 + 20 + 30) / 3").unwrap(), 20.0);
    }

    #[test]
    fn test_compound_interest_formula() {
        // P * (1 + r)^n where P=1000, r=0.05, n=2
        // 1000 * (1 + 0.05) ^ 2 = 1000 * 1.1025 = 1102.5
        let result = paginate_results("1000 * (1 + 0.05) ^ 2").unwrap();
        assert!((result - 1102.5).abs() < 1e-10);
    }

    #[test]
    fn test_nested_arithmetic() {
        // ((2 + 3) * (7 - 4)) / (1 + 2) = 15 / 3 = 5
        assert_eq!(
            paginate_results("((2 + 3) * (7 - 4)) / (1 + 2)").unwrap(),
            5.0
        );
    }

    // ---- Zero-valued expressions --------------------------------------------

    #[test]
    fn test_zero_result() {
        assert_eq!(paginate_results("5 - 5").unwrap(), 0.0);
    }

    #[test]
    fn test_zero_times_expression() {
        assert_eq!(paginate_results("0 * (999 + 1)").unwrap(), 0.0);
    }

    // ---- Large numbers ------------------------------------------------------

    #[test]
    fn test_large_exponent() {
        let result = paginate_results("2 ^ 30").unwrap();
        assert_eq!(result, 1073741824.0);
    }

    #[test]
    fn test_large_chain() {
        let result = paginate_results("1000000 + 2000000 * 3").unwrap();
        assert_eq!(result, 7000000.0);
    }
}

